const choice = (id, prompt, options, answer, hint, explain, viz) => ({id, type:'choice', prompt, options, answer, hint, explain, viz});
const input = (id, prompt, answer, hint, explain, viz, placeholder='例如 3/5') => ({id, type:'input', prompt, answer, hint, explain, viz, placeholder});
const strip = (n,d) => ({type:'strip',n,d});
const line = (n,d) => ({type:'line',n,d});
const grid = n => ({type:'grid',n,d:100});

export function questions(key, phase, variant=0) {
  const fresh = variant % 2 === 1;
  if (key === 'meaning') {
    if (phase === 'placement') return [
      choice('m-p1','一条纸带被分成下面的 4 块。蓝色的 1 块一定是这条纸带的 1/4 吗？',['一定是','不是，因为这 4 块没有平均分'],1,'分成 4 块还不够，每一块必须一样大。','分数里的“4”指平均分成 4 份。这里每块大小不同。',{type:'unequal'}),
      input('m-p2','整条纸带是 1。蓝色部分是它的几分之几？','2/5','先数一共平均分了几份，再数蓝色的份数。','平均分成 5 份，取了 2 份，所以是 2/5。',strip(2,5)),
      choice('m-p3','3/7 中，数字 7 告诉我们什么？',['取了 7 份','一个整体被平均分成 7 份','有 7 个整体'],1,'分母描述每一份是怎么来的。','分母 7 表示把一个整体平均分成 7 份；分子 3 表示取其中的 3 份。'),
    ];
    if (phase === 'practice') return [
      {id:'m-g1',type:'shade',prompt:'把整条纸带的 3/4 涂成蓝色。点一下可以涂色，再点一下取消。',d:4,n:3,hint:'4 告诉你一共有 4 个相等的部分，3 告诉你选其中的 3 个。',explain:'取 4 个相等部分中的 3 个，就是 3/4。'},
      input('m-g2','蓝色部分是整条纸带的几分之几？','4/6','下面一共有 6 个相等的部分。蓝色的有几个？','平均分成 6 份，蓝色有 4 份，所以写作 4/6（也可以写成 2/3）。',strip(4,6)),
      choice('m-g3','两张一样大的纸，一张取 3/4，另一张取 3/8。哪张取的多？',['3/4 更多','3/8 更多','一样多'],0,'取的份数相同，但每份大小不同。分成 4 份时，每份更大。','相同的整体，分成 4 份的每份比 8 份的大。都取 3 份，3/4 更大。',{type:'pair',n:3,d:4,n2:3,d2:8}),
    ];
    const n = fresh ? 3 : 5, d = fresh ? 7 : 8;
    return [
      input('m-c1','蓝色部分占整条纸带的多少？',`${n}/${d}`,'“整个纸带平均分成几份”写在下面，“取了几份”写在上面。',`一共有 ${d} 个相等部分，取了 ${n} 份，所以是 ${n}/${d}。`,strip(n,d)),
      {id:'m-c2',type:'shade',prompt:`涂出这条纸带的 ${fresh?'2/5':'3/7'}。`,d:fresh?5:7,n:fresh?2:3,hint:'只需要选中分子所说的份数。',explain:'先确认整体平均分成分母所说的份数，再取其中的分子份。'},
      choice('m-c3','小安说：“分成 5 块，取 2 块，就是 2/5。”还需要确认什么？',['每块是否一样大','纸带是不是蓝色','取的是不是左边两块'],0,'分数的每一份必须等大。','只有把一个整体平均分成 5 份，取其中 2 份，才能这样表示。'),
      choice('m-c4','两个大小不同的蛋糕，各取 1/2。拿到的蛋糕一定一样多吗？',['一定一样多','不一定，还要看整个蛋糕有多大'],1,'一半是相对于各自的整个蛋糕而言的。','分数相同也要看“整体”。大蛋糕的一半，比小蛋糕的一半多。'),
    ];
  }
  if (key === 'equivalent') {
    if (phase === 'placement') return [
      choice('e-p1','同样长的两条纸带，哪一组涂色一样多？',['1/2 与 2/4','1/2 与 1/4','1/2 与 2/3'],0,'把半张纸再分细一些，涂色总量没有变。','1/2 和 2/4 表示同样大小的部分。'),
      input('e-p2','在同一条数轴上，2/3 = ?/6。只填分子。','4','把每个三分之一再平均分成 2 份。','分母 3 乘 2 变成 6，分子 2 也乘 2，得到 4/6。',line(2,3),'填一个整数'),
      choice('e-p3','1/2 的分子和分母都加 1，得到 2/3。大小不变吗？',['不变','变了，2/3 比 1/2 大'],1,'想一想它们在数轴上的位置。','等值分数可以由分子、分母同乘一个非零数得到，同时加 1 通常会改变大小。'),
    ];
    if (phase === 'practice') return [
      input('e-g1','1/2 = ?/8。只填分子。','4','每个二分之一再分成 4 份。','分母乘 4，分子也乘 4：1/2 = 4/8。',{type:'pair',n:1,d:2,n2:4,d2:8},'填一个整数'),
      choice('e-g2','3/4 和 6/8 的涂色终点为什么重合？',['因为两个数都变大了','因为整体和涂色总量都没有改变，只把每份又分成了 2 份','因为分子加了 3'],1,'比较每一条纸带的整体长度和蓝色长度。','同一个整体中，每份再一分为二，份数和总份数一起变成原来的 2 倍，涂色总量不变。',{type:'pair',n:3,d:4,n2:6,d2:8}),
      input('e-g3','数轴上的点是 2/5。写出分母为 10 的等值分数。','4/10','从五等份变成十等份，每份又分成了 2 份。','2/5 和 4/10 都在 0 到 1 的同一个位置。',line(2,5)),
    ];
    return [
      input('e-c1',fresh?'3/5 = ?/10。只填分子。':'3/4 = ?/12。只填分子。',fresh?'6':'9','分母乘了几，分子也乘几。',fresh?'分子和分母都乘 2，得到 6/10。':'分子和分母都乘 3，得到 9/12。',null,'填一个整数'),
      choice('e-c2','下面两个分数落在数轴的同一个位置。最好的解释是什么？',['分子一样大','整体相同、表示的量相同，分法不同','只要分子分母都增加，就相等'],1,'关注从 0 出发走了多远。','4/6 与 2/3 表示同一个量，因此在数轴上的位置相同。',{type:'equivalentLine',n:2,d:3,n2:4,d2:6}),
      choice('e-c3',fresh?'2/5 的分子、分母都加 2，得到 4/7。它们一定相等吗？':'3/5 的分子、分母都加 1，得到 4/6。它们一定相等吗？',['相等','不相等'],1,'等值分数的关键是分子、分母按同样的倍数变化。','给分子和分母加同一个数，不能保证比值不变。'),
      input('e-c4',fresh?'写出分母为 12、与 2/3 等值的分数。':'写出分母为 15、与 2/5 等值的分数。',fresh?'8/12':'6/15','保持整体和涂色大小不变，再把每一份等分。',fresh?'2/3 = 8/12，分子分母都乘 4。':'2/5 = 6/15，分子分母都乘 3。'),
    ];
  }
  if (phase === 'placement') return [
    input('d-p1','把 7/10 写成小数。','0.7','小数点后第一位，数的是十分之一。','7 个十分之一就是 0.7。',null,'例如 0.5'),
    input('d-p2','把 6/100 写成小数。','0.06','没有整十分之一，十分位要写 0。','6 个百分之一就是 0.06，不是 0.6。',null,'例如 0.05'),
    choice('d-p3','0.3 和 0.30 的大小有什么关系？',['0.3 更大','0.30 更大','相等'],2,'3 个十分之一有多少个百分之一？','3/10 = 30/100，所以 0.3 = 0.30。'),
  ];
  if (phase === 'practice') return [
    input('d-g1','把这 27 个百分之一写成小数。','0.27','2 个十分之一，再加 7 个百分之一。','27/100 = 0.27。整块方格是 1。',grid(27),'例如 0.25'),
    input('d-g2','把 0.4 写成分母为 10 的分数。','4/10','0.4 中的 4 在十分位。','0.4 表示 4 个十分之一，就是 4/10。',line(4,10)),
    choice('d-g3','0.08 和 0.8，哪个更大？',['0.08 更大','0.8 更大','一样大'],1,'0.8 = 80/100，比 8/100 多。','0.08 是 8 个百分之一，0.8 是 80 个百分之一。'),
  ];
  return [
    input('d-c1',`把 ${fresh?63:43}/100 写成小数。`,fresh?'0.63':'0.43','十位上的格数对应十分位，剩下的小格数对应百分位。',fresh?'63/100 = 0.63。':'43/100 = 0.43。',null,'例如 0.25'),
    input('d-c2',`把 ${fresh?9:4}/100 写成小数。`,fresh?'0.09':'0.04','不足 1 个十分之一，十分位要写 0。',fresh?'9/100 = 0.09。':'4/100 = 0.04。',null,'例如 0.05'),
    input('d-c3',`把 ${fresh?'0.6':'0.8'} 写成分母为 100 的分数。`,fresh?'60/100':'80/100','1 个十分之一等于 10 个百分之一。',fresh?'0.6 = 6/10 = 60/100。':'0.8 = 8/10 = 80/100。',null),
    choice('d-c4','0.5 和 50/100 在数轴上会怎样？',['0.5 在左边','50/100 在左边','落在同一个点'],2,'它们都表示整体的一半。','0.5 = 5/10 = 50/100，都是从 0 到 1 的一半位置。'),
  ];
}

export function grade(q, answer) {
  if (q.type === 'choice') return Number.isInteger(answer) && answer === q.answer;
  if (q.type === 'shade') return Array.isArray(answer) && new Set(answer).size === q.n && answer.every(x=>Number.isInteger(x)&&x>=0&&x<q.d);
  const value = String(answer).trim().replaceAll('／','/').replaceAll('．','.').replace(/\s/g,'');
  // Fractions retain the requested denominator except an explicitly accepted simplification.
  if (q.answer.includes('/')) return value === q.answer || (q.id==='m-g2' && value === '2/3');
  return /^\d+(\.\d+)?$/.test(value) && Number(value) === Number(q.answer);
}
